    { id="01-7", start="天裔精靈", name="微風島", map=2521, lv={1, 12}, video="04:07", test=nil, alt=nil, when={race={"天裔精靈"}}, tips={{k="交通", text="跨族起點從莫高雷 Skywatcher Plateau 南側碼頭（34.30, 25.80）搭割天者號，在瓦拉納爾西碼頭（57.90, 80.90）下船，再沿路北上坦德爾林地。", s={{"跨族起點從莫高雷 Skywatcher Plateau 南側碼頭（34.30, 25.80）搭割天者號，在瓦拉納爾西碼頭（57.90, 80.90）下船，再沿路北上坦德爾林地"}}}, {k="提醒", text="抵達瓦拉納爾後沿大道北上坦德爾林地。其他部落可做共用支線，種族限定與未解鎖的前置步驟由插件過濾。1-3 級可先沿坦德爾林地打飛狐幼崽與捲雲蜂，再做可接的採集和村落支線。若已清完可接任務仍不足 12，回莫高雷接血蹄村支線補足。", s={{"抵達瓦拉納爾後沿大道北上坦德爾林地"}, {"其他部落可做共用支線，種族限定與未解鎖的前置步驟由插件過濾"}, {"1-3 級可先沿坦德爾林地打飛狐幼崽與捲雲蜂，再做可接的採集和村落支線"}, {"若已清完可接任務仍不足 12，回莫高雷接血蹄村支線補足"}}}, {k="取捨", text="本島主線依序走坦德爾、申德村、瓦拉納爾、奧基爾聖殿。還沒到12級可先做果園或影風森林支線，再搭飛艇。", s={{"本島主線依序走坦德爾、申德村、瓦拉納爾、奧基爾聖殿"}, {"還沒到12級可先做果園或影風森林支線，再搭飛艇"}}}, {k="取捨", text="村旁學徒和強盜任務可一起接。也可同時接角鷹獸騷擾（Hippogryph Harassment）角鷹獸騷擾。群爪問題（The Problem With Prideclaws）給簡易皮革背袋。愛管閒事的法師（Meddlesome Mages）可選潮汐流轉塑像。完成火之召喚可取得充能烈焰圖騰。", s={{"村旁學徒和強盜任務可一起接"}, {"也可同時接角鷹獸騷擾（Hippogryph Harassment）角鷹獸騷擾", {race={"天裔精靈"}}}, {"群爪問題（The Problem With Prideclaws）給簡易皮革背袋"}, {"愛管閒事的法師（Meddlesome Mages）可選潮汐流轉塑像", {class={"DRUID"}}}, {"完成火之召喚可取得充能烈焰圖騰", {class={"SHAMAN"}}}}}, {k="提醒", text="離島兩個銜接任務 接下來的事、陶土議會 顯示為 13 級任務，QuestieDB 最低可接等級是 7，主線跑完就能接。", s={{"離島兩個銜接任務 接下來的事、陶土議會 顯示為 13 級任務，QuestieDB 最低可接等級是 7，主線跑完就能接"}}}}, dungeon=nil, grind={{mob="年幼的弗德飛狐", lv={1, 1}, map=2521, x=44.87, y=25.54, note="密集／一般怪／可逐隻開怪，留意鄰近蜂群／坦德爾林地，1-2 級可先在起點附近升級"}, {mob="高地強盜", lv={7, 7}, map=2521, x=48.56, y=37.18, note="密集／一般怪／強盜會成群，先清營地邊緣／申德高地，與犯罪元素及被偷走的風石同行"}, {mob="奧拉凱斯追風者", lv={10, 11}, map=2521, x=63.31, y=37.39, note="密集／一般怪／混有步行兵，先從營地外側拉／影風森林，順做不屑為伍也不夠格之人，接近 12 級時補經驗"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
