    { id="02-8", start=nil, name="貧瘠之地 十字路口", map=1413, lv={12, 16}, video="04:35", test=nil, alt=nil, when=nil, tips={{k="交通", text="第 4 步開十字路口並綁爐石；第一趟棘齒城開布萊格；離站到弗雷薩一側等提里斯法林地線。", s={{"第 4 步開十字路口並綁爐石"}, {"第一趟棘齒城開布萊格"}, {"離站到弗雷薩一側等提里斯法林地線"}}}, {k="取捨", text="值得做 遺忘之池 → 死水綠洲 → 變異的生物，只有交完才開往銀松的 茉拉·符文圖騰。TUGs 把 變異的生物 排到另一次貧瘠之地，本路線提早清完，方便下一站直接交 茉拉·符文圖騰。", s={{"值得做 遺忘之池 → 死水綠洲 → 變異的生物，只有交完才開往銀松的 茉拉·符文圖騰"}, {"TUGs 把 變異的生物 排到另一次貧瘠之地，本路線提早清完，方便下一站直接交 茉拉·符文圖騰"}}}, {k="取捨", text="北側沼澤護送、礦洞與 被竊的貨物 留貧瘠之地 棘齒城與陶拉祖營地一起做，第一次到棘齒城只清近岸海盜。", s={{"北側沼澤護送、礦洞與 被竊的貨物 留貧瘠之地 棘齒城與陶拉祖營地一起做，第一次到棘齒城只清近岸海盜"}}}, {k="取捨", text="雷霆崖 藥劑師紮瑪、哈繆爾·符文圖騰、至死方休 看是否順路；若已 16 級又無哀嚎隊伍，可直接轉銀松。", s={{"雷霆崖 藥劑師紮瑪、哈繆爾·符文圖騰、至死方休 看是否順路"}, {"若已 16 級又無哀嚎隊伍，可直接轉銀松"}}}, {k="提醒", text="14-16 可選怒焰裂谷；主線無須排到副本。未滿 16 可提前做貧瘠之地 棘齒城與陶拉祖營地的 埃其亞基、鷹身人首領，或在死水綠洲（約 55, 42）打變異龜，走下一站前先交現成的任務。", s={{"14-16 可選怒焰裂谷"}, {"主線無須排到副本"}, {"未滿 16 可提前做貧瘠之地 棘齒城與陶拉祖營地的 埃其亞基、鷹身人首領，或在死水綠洲（約 55, 42）打變異龜，走下一站前先交現成的任務"}}}}, dungeon=nil, grind={{mob="敏捷的平原陸行鳥", lv={12, 13}, map=1413, x=54.69, y=38.5, note="十字路口東南的開闊平原，密度中等、普通怪。附近有半人馬巡邏，沿路挑落單的陸行鳥，適合 12-13 級補開局經驗。"}, {mob="綠洲鉗嘴龜", lv={15, 16}, map=1413, x=55, y=42.23, note="死水綠洲岸邊密度高，普通怪；往外拉，留意附近的科卡爾。可同步補變異的鉗嘴龜殼。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
