        {t="accept", q=78270, opt=true, desc="先做這個準備，再到銀松森林做 澤索司號角；這是副本潛入的可選開門方法。", tag="可跳過", npc="維尼克斯", tgt="維尼克斯", map=1442, x=58.22, y=51.74, when={lvMin=23, class={"ROGUE"}}},
