    { id="02-13", start=nil, name="千針石林", map=1441, lv={27, 28}, video="05:25", test=nil, alt=nil, when=nil, tips={{k="交通", text="奧格瑪進城飛陶拉祖；從貧瘠之地南端搭大升降梯下谷，亂風崗首次開點。雷霆崖有 神聖之火 才繞。", s={{"奧格瑪進城飛陶拉祖"}, {"從貧瘠之地南端搭大升降梯下谷，亂風崗首次開點"}, {"雷霆崖有 神聖之火 才繞"}}}, {k="取捨", text="值得做。石爪山脈 烈日石居的信直接交大升降梯守衛。亂風崗西邊的補給箱、三種鷹身人和耐力試煉共用區域。", s={{"值得做"}, {"石爪山脈 烈日石居的信直接交大升降梯守衛"}, {"亂風崗西邊的補給箱、三種鷹身人和耐力試煉共用區域"}}}, {k="取捨", text="之後順路。影片先講梣谷，再提中途跑一趟千針石林。這裡把亂風崗短訪排在梣谷主線前；閃光平原整圈留千針石林 閃光平原。", s={{"之後順路"}, {"影片先講梣谷，再提中途跑一趟千針石林"}, {"這裡把亂風崗短訪排在梣谷主線前"}, {"閃光平原整圈留千針石林 閃光平原"}}}, {k="取捨", text="可跳過。拉克塔護送、豹籠和西側巡邏後續較費時；有隊友或正在經過目標再做。", s={{"可跳過"}, {"拉克塔護送、豹籠和西側巡邏後續較費時"}, {"有隊友或正在經過目標再做"}}}, {k="提醒", text="若要打剃刀沼澤，入口在大升降梯前的貧瘠之地南端。未達本段預期進度，可以在亂風崗西側的尖嘯鷹身人坡地（約27, 51）補經驗。", s={{"若要打剃刀沼澤，入口在大升降梯前的貧瘠之地南端"}, {"未達本段預期進度，可以在亂風崗西側的尖嘯鷹身人坡地（約27, 51）補經驗"}}}}, dungeon=nil, grind={{mob="雜毛土狼", lv={26, 27}, map=1441, x=29.76, y=51.39, note="亂風崗西側谷地密度中等，普通怪；在谷底逐隻打，不必繞到鷹身人營地。"}, {mob="尖嘯的鷹身人", lv={28, 29}, map=1441, x=26.49, y=52.26, note="西側鷹身人坡地密度中等，普通怪；營地同時有其他鷹身人，沿坡緣挑落單，可順做尖嘯鷹身人任務。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
