    { id="02-14", start=nil, name="梣谷", map=1440, lv={27, 30}, video="05:16", test=nil, alt=nil, when=nil, tips={{k="交通", text="先開碎木崗哨，再開佐拉姆加；依待交任務選碎木崗哨、烈日石居、十字路口，或從佐拉姆加直接飛奧格瑪。保留塔倫米爾爐石。", s={{"先開碎木崗哨，再開佐拉姆加"}, {"依待交任務選碎木崗哨、烈日石居、十字路口，或從佐拉姆加直接飛奧格瑪"}, {"保留塔倫米爾爐石"}}}, {k="取捨", text="值得做。碎木崗哨南側先驅者、西南湖元素、北側薩特各做一圈；佐拉姆加的熊怪與洞穴符咒一起解。", s={{"值得做"}, {"碎木崗哨南側先驅者、西南湖元素、北側薩特各做一圈"}, {"佐拉姆加的熊怪與洞穴符咒一起解"}}}, {k="取捨", text="可跳過。三隻獵物會巡邏，只在順路遇到時打。散頁沒集滿可留到日後交易，不必反覆刷。", s={{"可跳過"}, {"三隻獵物會巡邏，只在順路遇到時打"}, {"散頁沒集滿可留到日後交易，不必反覆刷"}}}, {k="取捨", text="之後順路。29級後若本來就要跑十字路口和奧格瑪，可先接 瘋狂的蟲群，交奧格瑪後接 瘋狂的蟲群。到千針石林 閃光平原交 瘋狂的蟲群 才能接 瘋狂的蟲群；與本段交通不順路就略過。", s={{"之後順路"}, {"29級後若本來就要跑十字路口和奧格瑪，可先接 瘋狂的蟲群，交奧格瑪後接 瘋狂的蟲群"}, {"到千針石林 閃光平原交 瘋狂的蟲群 才能接 瘋狂的蟲群"}, {"與本段交通不順路就略過"}}}, {k="提醒", text="未到30級優先補薩特（約67, 57）或薊皮熊怪（約32, 38）。有隊伍可在佐拉姆海岸下黑暗深淵；若隊友未到齊，先繼續本段。", s={{"未到30級優先補薩特（約67, 57）或薊皮熊怪（約32, 38）"}, {"有隊伍可在佐拉姆海岸下黑暗深淵"}, {"若隊友未到齊，先繼續本段"}}}}, dungeon=nil, grind={{mob="魔草巡影者", lv={26, 27}, map=1440, x=66.85, y=56.99, note="魔草薩特營地外側密度中等，普通怪；同類巡邏與其他薩特會靠近，沿營地邊緣清，能順便收薩特之角。"}, {mob="幽爪前鋒", lv={27, 28}, map=1440, x=71.91, y=58.02, note="碎木崗哨北側林地密度中等，普通怪；用開闊地逐隻打，離飛行點近，適合不想進薩特營地時補經驗。"}, {mob="薩維亞盜賊", lv={29, 30}, map=1440, x=78.83, y=46.66, note="薩維亞營地密度中等，普通怪；留意隱匿與巡邏怪，先清外圍再走內側。適合 29 級最後一段，亦可順手補薩特之角。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
