    { id="03-18", start=nil, name="淒涼之地 葬影村第一次", map=1443, lv={32, 34}, video="22:21", test=nil, alt=nil, when=nil, tips={{k="取捨", text="吉爾吉斯線 吉爾吉斯部族／偷取物資 順南路。已選瑪格拉姆或聲望相反時，跳過這兩步與淒涼之地 葬影村的吉爾吉斯後續。", s={{"吉爾吉斯線 吉爾吉斯部族／偷取物資 順南路"}, {"已選瑪格拉姆或聲望相反時，跳過這兩步與淒涼之地 葬影村的吉爾吉斯後續"}}}, {k="取捨", text="葬影村去西岸時一起做兩個水域任務與上古之書。雷斧堡壘先打聖光節杖與埃魯索斯之手，若進度不足再到第二趟補交。", s={{"葬影村去西岸時一起做兩個水域任務與上古之書"}, {"雷斧堡壘先打聖光節杖與埃魯索斯之手，若進度不足再到第二趟補交"}}}, {k="取捨", text="沒遇到車隊就直接走，不原地等護送。保留荊棘谷狩獵  到下一站。", s={{"沒遇到車隊就直接走，不原地等護送"}, {"保留荊棘谷狩獵  到下一站"}}}, {k="提醒", text="前往荊棘谷前若未到 34，在科多墓地周圍打普通半人馬（約 56, 60-68），或在西岸打滑刃納迦（35.91, 28.84）。", s={{"前往荊棘谷前若未到 34，在科多墓地周圍打普通半人馬（約 56, 60-68），或在西岸打滑刃納迦（35.91, 28.84）"}}}}, dungeon=nil, grind={{mob="恐怖猛鷲", lv={32, 33}, map=1443, x=56.04, y=64.79, note="科多墓地東側外圍，密度較低、普通怪。留意其他腐化鳥，離墓地任務近，適合順手補少量經驗。"}, {mob="滑刃納迦", lv={32, 33}, map=1443, x=35.16, y=27.79, note="西岸水邊，密度高、普通怪。沿岸挑落單，留意同區巫女，西岸任務可以一起清。"}, {mob="滑刃巫女", lv={32, 33}, map=1443, x=35.91, y=28.84, note="西岸納迦區南端，密度中等、普通施法怪。把怪拉向岸邊再打，避免水下龍蝦人連帶入戰。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
