    { id="03-19", start=nil, name="荊棘谷 第一次", map=1434, lv={34, 37}, video="23:20", test=nil, alt=nil, when=nil, tips={{k="取捨", text="藏寶海灣第 1 次到訪主要開飛點並接任務；約 35 級只交第一批：血頂巨魔的耳朵、調查營地、供與求、歌唱水晶碎片、惡性競爭，及已做完的 任何有價值之物／Zimmix's Great Escape。交 供與求 和 歌唱水晶碎片 才開 收集鱷魚皮 和 風險投資公司。", s={{"藏寶海灣第 1 次到訪主要開飛點並接任務"}, {"約 35 級只交第一批：血頂巨魔的耳朵、調查營地、供與求、歌唱水晶碎片、惡性競爭，及已做完的 任何有價值之物／Zimmix's Great Escape"}, {"交 供與求 和 歌唱水晶碎片 才開 收集鱷魚皮 和 風險投資公司"}}}, {k="取捨", text="先別交  風險投資公司（Venture Company Mining）、 刨花皮靴（Excelsior），留荊棘谷 藏寶海灣併南谷回收。收集鱷魚皮 完成後留荊棘谷 藏寶海灣先交，再接 刨花皮靴。", s={{"先別交  風險投資公司（Venture Company Mining）、 刨花皮靴（Excelsior），留荊棘谷 藏寶海灣併南谷回收"}, {"收集鱷魚皮 完成後留荊棘谷 藏寶海灣先交，再接 刨花皮靴"}}}, {k="取捨", text="42 級回訪才排血帆 血帆海盜→血帆海盜→血帆海盜→血帆海盜→血帆海盜，併 海盜的眼睛／鼻煙、贊吉爾的秘密、嚇唬病鬼→向馬克基雷回報→討債行動。先別排 荊棘谷熱疫／荊棘谷熱疫 熱疫、瓶中信→ 瓶中信、 船長的箱子、威士忌斯利姆的酒 酒和 妳自己的OOX OOX，見荊棘谷 藏寶海灣的 45 級後清單。影片的分次交原則保留，具體 ID 為路線配置。", s={{"42 級回訪才排血帆 血帆海盜→血帆海盜→血帆海盜→血帆海盜→血帆海盜，併 海盜的眼睛／鼻煙、贊吉爾的秘密、嚇唬病鬼→向馬克基雷回報→討債行動"}, {"先別排 荊棘谷熱疫／荊棘谷熱疫 熱疫、瓶中信→ 瓶中信、 船長的箱子、威士忌斯利姆的酒 酒和 妳自己的OOX OOX，見荊棘谷 藏寶海灣的 45 級後清單"}, {"影片的分次交原則保留，具體 ID 為路線配置"}}}, {k="取捨", text="先把獵龍解到 獵龍，再和 格羅姆高保衛戰 一起打鞭尾迅猛龍。歌唱水晶碎片 先打北邊的晶脊蜥蜴，第一趟無須繞去南谷。", s={{"先把獵龍解到 獵龍，再和 格羅姆高保衛戰 一起打鞭尾迅猛龍"}, {"歌唱水晶碎片 先打北邊的晶脊蜥蜴，第一趟無須繞去南谷"}}}, {k="取捨", text="若 34 級空白起步，先做三條獵線頭兩輪，並做格羅姆高與血頂巨魔群。深喉獵豹同時解 獵豹／摩克薩爾丁的魔法，普通辛達爾 獵虎 同圈處理。奈茲裏奧克 的三件戰利品留荊棘谷 藏寶海灣和裂骨項鏈一起做。荊棘谷的青山 -荊棘谷的青山 - 第四章 有散頁再交。", s={{"若 34 級空白起步，先做三條獵線頭兩輪，並做格羅姆高與血頂巨魔群"}, {"深喉獵豹同時解 獵豹／摩克薩爾丁的魔法，普通辛達爾 獵虎 同圈處理"}, {"奈茲裏奧克 的三件戰利品留荊棘谷 藏寶海灣和裂骨項鏈一起做"}, {"荊棘谷的青山 -荊棘谷的青山 - 第四章 有散頁再交"}}}, {k="提醒", text="35 級可組沉沒之城（The Drowned City，35-40）。先確認隊伍與相關任務，從格羅姆高西邊海底入場。", s={{"35 級可組沉沒之城（The Drowned City，35-40）"}, {"先確認隊伍與相關任務，從格羅姆高西邊海底入場"}}}, {k="提醒", text="約 34-35 級先在北谷打血頂巨魔（29.76, 21.62）；36 級後轉格羅姆高東南的食人魔營地（35.55, 30.92），缺多少就在這裡補到 37 再搭飛艇。先交營地裡已完成的任務。", s={{"約 34-35 級先在北谷打血頂巨魔（29.76, 21.62）"}, {"36 級後轉格羅姆高東南的食人魔營地（35.55, 30.92），缺多少就在這裡補到 37 再搭飛艇"}, {"先交營地裡已完成的任務"}}}}, dungeon=nil, grind={{mob="血頂戰士", lv={33, 34}, map=1434, x=29.76, y=21.62, note="北谷血頂遺跡，密度中等、普通怪。沿外牆挑落單，留意附近的血頂薩滿，適合 34 級補經驗。可同趟收旋風武器任務用的血頂獠牙。"}, {mob="鞭尾迅猛龍", lv={35, 36}, map=1434, x=30.55, y=22.47, note="格羅姆高以北的林地，密度高、普通怪。沿路找單隻，避開下水後的鹽鱗精英，可順做迅猛龍獵殺。"}, {mob="莫什奧格蠻卒", lv={36, 37}, map=1434, x=35.55, y=30.92, note="格羅姆高東南食人魔營地外圍，密度中等、普通怪。避開巫醫與稀有怪羅洛克，36 級後可就近補到 37。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
