    { id="03-23", start=nil, name="阿拉希高地 落錘鎮第二次", map=1417, lv={38, 40}, video="25:50", test=nil, alt=nil, when=nil, tips={{k="取捨", text="石拳、迅猛龍與辛迪加進階任務可在回訪時一起清。低階版沒做過就跳過同名後續。禁錮之石  順環線摸完，打開鑰匙之石 弗茲魯克適合有隊伍才追。", s={{"石拳、迅猛龍與辛迪加進階任務可在回訪時一起清"}, {"低階版沒做過就跳過同名後續"}, {"禁錮之石  順環線摸完，打開鑰匙之石 弗茲魯克適合有隊伍才追"}}}, {k="取捨", text="法迪爾海灣一次接打撈、水下寶藏和船長的復仇。先完成 水下寶藏 解鎖 水下寶藏，接 水下寶藏 領尋寶護目鏡，並順手做水下的 深海打撈／船長的復仇。水下寶藏 留到荊棘谷 藏寶海灣，水下寶藏 回海灣的交件另候順路。", s={{"法迪爾海灣一次接打撈、水下寶藏和船長的復仇"}, {"先完成 水下寶藏 解鎖 水下寶藏，接 水下寶藏 領尋寶護目鏡，並順手做水下的 深海打撈／船長的復仇"}, {"水下寶藏 留到荊棘谷 藏寶海灣，水下寶藏 回海灣的交件另候順路"}}}, {k="取捨", text="影片建議激流堡有餘力再做。要省跑圖，先做水晶和落錘近郊，激流堡後段 阿拉索符印-托卡拉爾 可跳。", s={{"影片建議激流堡有餘力再做"}, {"要省跑圖，先做水晶和落錘近郊，激流堡後段 阿拉索符印-托卡拉爾 可跳"}}}, {k="提醒", text="途經斯通納德先開飛點。悲傷沼澤任務留悲傷沼澤 斯通納德。", s={{"途經斯通納德先開飛點"}, {"悲傷沼澤任務留悲傷沼澤 斯通納德"}}}, {k="提醒", text="前往大河林地前若未到 40，先清落錘鎮東側乾鬚峽谷的普通狗頭人（約 84, 31）。怪物開始轉灰時，改打枯木村外圍的普通巨魔（約 68, 69）。", s={{"前往大河林地前若未到 40，先清落錘鎮東側乾鬚峽谷的普通狗頭人（約 84, 31）"}, {"怪物開始轉灰時，改打枯木村外圍的普通巨魔（約 68, 69）"}}}}, dungeon=nil, grind={{mob="枯鬚勘探員", lv={37, 38}, map=1417, x=84.35, y=30.75, note="落錘鎮東側枯鬚峽谷深處，密度中等、普通怪。洞道狹窄且可能碰到稀有地卜師弗林塔格，從入口逐段推進。"}, {mob="枯鬚掘地工", lv={36, 37}, map=1417, x=83.42, y=32.06, note="枯鬚峽谷洞道，密度高、普通怪。與勘探員混合，可和水晶任務同趟，留意洞內回頭時的重生。"}, {mob="水浪流放者", lv={38, 39}, map=1417, x=67.38, y=28.52, note="落錘鎮西北水元素區，密度高、普通怪。比狗頭人稍高等，可打到 40。可同趟收集旋風武器任務的元素符咒。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
