    { id="03-24", start=nil, name="大河林地 羅格瑪第一次", map=2548, lv={40, 41}, video="26:31", test=nil, alt=nil, when=nil, tips={{k="取捨", text="第一次先清農場、豺狼人、河岸及羅格瑪周邊野獸。Chogg'Zac Twilight No More! 和後續送頭線留有隊伍再做，博德羅克的野豬和採石可直接接。42 級以上的暮光和海岸留大河林地博德羅克與火線港，照影片分兩次跑。", s={{"第一次先清農場、豺狼人、河岸及羅格瑪周邊野獸"}, {"Chogg'Zac Twilight No More! 和後續送頭線留有隊伍再做，博德羅克的野豬和採石可直接接"}, {"42 級以上的暮光和海岸留大河林地博德羅克與火線港，照影片分兩次跑"}}}, {k="取捨", text="在這站先開羅格瑪飛點，往返卡加斯或斯通納德可少跑地面。補給可找 Toka。", s={{"在這站先開羅格瑪飛點，往返卡加斯或斯通納德可少跑地面"}, {"補給可找 Toka"}}}, {k="提醒", text="交完當站任務若未到 41，在 Na'zok 農場南側（70.62, 33.08）補普通野豬，或在羅格瑪南側野獸區（約 61, 50）續打。博德羅克的進階暮光任務留大河林地博德羅克與火線港。", s={{"交完當站任務若未到 41，在 Na'zok 農場南側（70.62, 33.08）補普通野豬，或在羅格瑪南側野獸區（約 61, 50）續打"}, {"博德羅克的進階暮光任務留大河林地博德羅克與火線港"}}}}, dungeon=nil, grind={{mob="低地禿鷲", lv={37, 38}, map=2548, x=61.44, y=50.71, note="羅格瑪南側草地，資料庫點位密集、普通怪。附近有 41-42 級精英野獸，沿路挑單隻；可同步補 Feathers for Fletching 的羽毛。"}, {mob="遠境堡斥候", lv={38, 39}, map=2548, x=60.33, y=57.94, note="羅格瑪以南的遠境堡斥候區，密度高、普通怪。留意牧師與其他斥候一起入戰，沿河外圍清並順做 Show Them How It's Done。"}, {mob="遠境堡牧師", lv={38, 39}, map=2548, x=48.62, y=64.43, note="南岸偏西，密度中等、普通施法怪。先打斷治療，別同時拉斥候；已走 Show Them How It's Done 西段時可順手補。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
