    { id="03-25", start=nil, name="荒蕪之地 卡加斯", map=1418, lv={41, 42}, video="28:03", test=nil, alt=nil, when=nil, tips={{k="取捨", text="石元素與荒蕪試劑 荒蕪之地的試劑 共享一部分怪點，先接齊再打。山狗下顎骨要 30，接著一路清，夠等就走。", s={{"石元素與荒蕪試劑 荒蕪之地的試劑 共享一部分怪點，先接齊再打"}, {"山狗下顎骨要 30，接著一路清，夠等就走"}}}, {k="取捨", text="冰霜之油、發條式同步協調陀螺儀和藥水都已備好才做 至關重要的冷卻劑-盧希恩的藥水。破碎的聯盟  留更高等或有隊伍。", s={{"冰霜之油、發條式同步協調陀螺儀和藥水都已備好才做 至關重要的冷卻劑-盧希恩的藥水"}, {"破碎的聯盟  留更高等或有隊伍"}}}, {k="提醒", text="影片把 40 級學騎術放在這次主城轉場。已滿 40 且有金幣，可以在路過本族訓練師時先學。參見文末「職業任務」及「40 級各族騎術」。", s={{"影片把 40 級學騎術放在這次主城轉場"}, {"已滿 40 且有金幣，可以在路過本族訓練師時先學"}, {"參見文末「職業任務」及「40 級各族騎術」"}}}, {k="提醒", text="離開卡加斯前若未到 42，在荒蕪之地西南打普通巨型石元素（約 6.65, 73.85）。石元素點擁擠時，沿卡加斯東南山脊打山狗和禿鷲。", s={{"離開卡加斯前若未到 42，在荒蕪之地西南打普通巨型石元素（約 6.65, 73.85）"}, {"石元素點擁擠時，沿卡加斯東南山脊打山狗和禿鷲"}}}}, dungeon=nil, grind={{mob="巨型石元素", lv={42, 44}, map=1418, x=6.65, y=73.85, note="卡加斯南方山壁，密度高、普通怪。附近有火煙食人魔，沿岩壁清外側；42 級前覺得吃力就改打山脊。"}, {mob="山脊巡行者族王", lv={40, 41}, map=1418, x=21.28, y=68.93, note="卡加斯東南山脊，密度中等、普通怪。避開精英與稀有巡邏，適合 41 級單練或石元素區擁擠時換點。"}, {mob="巨型禿鷲", lv={39, 41}, map=1418, x=15.03, y=60.1, note="卡加斯東南坡地，密度中等、普通怪。可與山脊巡行者輪打；有禿鷲翅膀或胃囊任務時一併收。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
