    { id="03-26", start=nil, name="荊棘谷 第二次", map=1434, lv={42, 45}, video="29:01", test=nil, alt=nil, when=nil, tips={{k="取捨", text="藏寶海灣第 2 趟先交 水下寶藏／風險投資公司／刨花皮靴 等已完成任務。血帆 血帆海盜→血帆海盜→血帆海盜 先跑近岸短段，開 血帆海盜 同做 海盜的眼睛／鼻煙；交 血帆海盜 才接 血帆海盜 打三船首領。討債 討債行動 需先交 嚇唬病鬼→向馬克基雷回報。影片要求逐環回港，這幾個解鎖點照走。", s={{"藏寶海灣第 2 趟先交 水下寶藏／風險投資公司／刨花皮靴 等已完成任務"}, {"血帆 血帆海盜→血帆海盜→血帆海盜 先跑近岸短段，開 血帆海盜 同做 海盜的眼睛／鼻煙"}, {"交 血帆海盜 才接 血帆海盜 打三船首領"}, {"討債 討債行動 需先交 嚇唬病鬼→向馬克基雷回報"}, {"影片要求逐環回港，這幾個解鎖點照走"}}}, {k="取捨", text="可在血帆船上先接  科泰羅的謎題（Cortello's Riddle），到悲傷沼澤 斯通納德時順路解第一段。刨花皮靴 和 風險投資公司 沒做完就順路補，避免為單件又飛一次。先處理岸上的 討債行動 再上船。", s={{"可在血帆船上先接  科泰羅的謎題（Cortello's Riddle），到悲傷沼澤 斯通納德時順路解第一段"}, {"刨花皮靴 和 風險投資公司 沒做完就順路補，避免為單件又飛一次"}, {"先處理岸上的 討債行動 再上船"}}}, {k="提醒", text="荊棘谷 藏寶海灣至大河林地博德羅克與火線港合計練到 45。若此站想先補少量經驗，收完血帆三船後打岸邊的普通血帆海盜（約 32, 79）。", s={{"荊棘谷 藏寶海灣至大河林地博德羅克與火線港合計練到 45"}, {"若此站想先補少量經驗，收完血帆三船後打岸邊的普通血帆海盜（約 32, 79）"}}}}, dungeon=nil, grind={{mob="血帆劍客", lv={41, 43}, map=1434, x=31.95, y=79.47, note="藏寶海灣外海灘，密度高、普通怪。先清岸上，留意其他玩家也在解血帆任務；船線做完可就近補經驗。"}, {mob="血帆術士", lv={41, 43}, map=1434, x=29.99, y=80.57, note="血帆南側岸邊，密度高、普通施法怪。先清同群近戰，再拉術士；岸上循環可省上船時間。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
