    { id="03-28", start=nil, name="大河林地 博德羅克與火線港第二次", map=2548, lv={42, 45}, video="29:35", test=nil, alt=nil, when=nil, tips={{k="取捨", text="先從羅格瑪往西，合併清教徒與救斥候 Carving a Path／Break Their Chains，組隊懸賞 Bring Me His Head 略過。北線缺前置可直去火線港。港口一起接魚人、螃蟹和海盜，清完再接 See Ya, Scallywags!／The Monster Surfaces。", s={{"先從羅格瑪往西，合併清教徒與救斥候 Carving a Path／Break Their Chains，組隊懸賞 Bring Me His Head 略過"}, {"北線缺前置可直去火線港"}, {"港口一起接魚人、螃蟹和海盜，清完再接 See Ya, Scallywags!／The Monster Surfaces"}}}, {k="提醒", text="不足 45 就在東風海岸（約 84, 35-43）沿岸打東海海盜與火槍手，港口附近可以補給。40-45 級有隊伍可下克羅多克要塞（Krol'dok Stronghold），先接羅格瑪的 Eye of Mugg／Tome of Twilight。", s={{"不足 45 就在東風海岸（約 84, 35-43）沿岸打東海海盜與火槍手，港口附近可以補給"}, {"40-45 級有隊伍可下克羅多克要塞（Krol'dok Stronghold），先接羅格瑪的 Eye of Mugg／Tome of Twilight"}}}, {k="交通", text="到 45 級後在火線港碼頭（80.60, 54.60）搭中立船到塔納利斯 熱砂港（68.60, 23.00），再往加基森。若要留在東部王國，可沿路回羅格瑪飛行點。從塔納利斯抵港的部落角色同樣要由陸路去羅格瑪開飛點。", s={{"到 45 級後在火線港碼頭（80.60, 54.60）搭中立船到塔納利斯 熱砂港（68.60, 23.00），再往加基森"}, {"若要留在東部王國，可沿路回羅格瑪飛行點"}, {"從塔納利斯抵港的部落角色同樣要由陸路去羅格瑪開飛點"}}}}, dungeon=nil, grind={{mob="東海海盜", lv={41, 42}, map=2548, x=84.49, y=39.35, note="火線港北側東風海岸，資料庫點位密集、普通怪。與火槍手混合，沿沙灘逐隻拉；可同步完成 Unfriendly Competition。"}, {mob="東海火槍手", lv={42, 43}, map=2548, x=84.29, y=39.09, note="東風海岸中段，資料庫點位密集、普通遠程怪。與海盜交錯，近戰可利用地形拉到岸側；適合補到 45 級。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
