    { id="04-29", start=nil, name="塔納利斯 熱砂港與加基森第一次", map=1446, lv={45, 47}, video="30:00", test=nil, alt=nil, when=nil, tips={{k="取捨", text="第一次熱砂港把海盜帽、擊殺、通緝與貨箱一起清。TUGs 先排菲拉斯再回頭清港口海盜；本路線從火線港乘船到熱砂港，可先清海岸並保留同樣的影片站序。", s={{"第一次熱砂港把海盜帽、擊殺、通緝與貨箱一起清"}, {"TUGs 先排菲拉斯再回頭清港口海盜"}, {"本路線從火線港乘船到熱砂港，可先清海岸並保留同樣的影片站序"}}}, {k="取捨", text="尖嘯者的靈魂 留菲拉斯 莫沙徹營地做；Dunemaul Dues 留砂槌營地；給馬克基雷的貨物 留到前往悲傷沼澤時在荊棘谷 藏寶海灣交。", s={{"尖嘯者的靈魂 留菲拉斯 莫沙徹營地做"}, {"Dunemaul Dues 留砂槌營地"}, {"給馬克基雷的貨物 留到前往悲傷沼澤時在荊棘谷 藏寶海灣交"}}}, {k="提醒", text="未到下一站所需等級，廢土營地 59.40,24.71、落帆海灣入口 70.90,42.48 的一般怪可循環打。已組祖爾法拉克可帶 聖甲蟲的殼、探水棒、巨魔調和劑，塔納利斯 加基森與砂槌營地交。", s={{"未到下一站所需等級，廢土營地 59.40,24.71、落帆海灣入口 70.90,42.48 的一般怪可循環打"}, {"已組祖爾法拉克可帶 聖甲蟲的殼、探水棒、巨魔調和劑，塔納利斯 加基森與砂槌營地交"}}}}, dungeon=nil, grind={{mob="南海海賊", lv={44, 45}, map=1446, x=70.9, y=42.48, note="落帆海灣入口，普通怪密集，海賊任務容易撞隊。沿外側往海灘清，可同步收海盜任務掉落。"}, {mob="南海劍客", lv={44, 45}, map=1446, x=72.42, y=46.52, note="碼頭外沿的普通怪，海賊入口被搶怪時換點。從外緣拉，避免同時引到碼頭守怪。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
