    { id="04-34", start=nil, name="灼熱峽谷 瑟銀哨塔", map=1427, lv={49, 50}, video="31:23", test=nil, alt=nil, when=nil, tips={{k="交通", text="先在瑟銀哨塔開部落飛點，完成後可飛幽暗城或落錘鎮，再接辛特蘭。", s={{"先在瑟銀哨塔開部落飛點，完成後可飛幽暗城或落錘鎮，再接辛特蘭"}}}, {k="取捨", text="四組殺怪可沿同一圈完成，被盜：鼓風機和望遠鏡 掉落不足先交別組；懸賞：工頭瑪托留斯 與 絕密配方！ 在同一洞內，能組隊再順路清。", s={{"四組殺怪可沿同一圈完成，被盜：鼓風機和望遠鏡 掉落不足先交別組"}, {"懸賞：工頭瑪托留斯 與 絕密配方！ 在同一洞內，能組隊再順路清"}}}, {k="取捨", text="瑟銀哨塔交完已達 50 可以離站。火炬後半與東南木製廁所各需額外折返，缺經驗再做。", s={{"瑟銀哨塔交完已達 50 可以離站"}, {"火炬後半與東南木製廁所各需額外折返，缺經驗再做"}}}, {k="提醒", text="尚差少量經驗，在大熔爐東側外圈 44.76,38.72 打重型作戰傀儡，或回北坡 41.21,23.33 打普通黑鐵工頭。", s={{"尚差少量經驗，在大熔爐東側外圈 44.76,38.72 打重型作戰傀儡，或回北坡 41.21,23.33 打普通黑鐵工頭"}}}}, dungeon=nil, grind={{mob="重型作戰魔像", lv={47, 49}, map=1427, x=44.76, y=38.72, note="大熔爐東緣的普通魔像，沿高處外圈打，可同步解擊殺。任務玩家多時別下熔爐底。"}, {mob="黑鐵監工", lv={47, 48}, map=1427, x=41.21, y=23.33, note="瑟銀哨塔南側的普通黑鐵怪，回飛點前可連打並補任務掉落。營地內可能連拉。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
