    { id="05-d22", start=nil, name="奧卡茲監獄", map=1445, lv={48, 53}, video=nil, test=nil, alt=nil, when=nil, tips={{k="取捨", text="優先走 The Missing Kor'kron 到 Thrall Needs to Know 的庫卡隆救援鏈；頭巾若一趟未湊滿，交件延後。", s={{"優先走 The Missing Kor'kron 到 Thrall Needs to Know 的庫卡隆救援鏈"}, {"頭巾若一趟未湊滿，交件延後"}}}, {k="說明", text="部落可避開塞拉摩；由蕨牆村到東北海岸後游泳。軍士在島側，副本門位於島塔地下走廊。", s={{"部落可避開塞拉摩"}, {"由蕨牆村到東北海岸後游泳"}, {"軍士在島側，副本門位於島塔地下走廊"}}}}, dungeon=true, grind=nil, after="04-34", entrance="塵泥沼澤 75.30, 14.10", pickup="前往悲傷沼澤時，未到 48 級可先開塵泥沼澤 蕨牆村飛行點。前往灼熱峽谷前，在奧格瑞瑪智慧谷索爾的大廳向伊崔格接 The Missing Kor'kron（34.28, 39.35），再飛蕨牆村找納澤爾·血矛。沿東北海岸游往奧卡茲島，在島側軍士處依序交 The Elite of the Elite、Right Place, Wrong Time，拿 No Orc Left Behind 再進島塔地下。留下 Thrall Needs to Know 至下次奧格瑞瑪。", pickupS={{"前往悲傷沼澤時，未到 48 級可先開塵泥沼澤 蕨牆村飛行點"}, {"前往灼熱峽谷前，在奧格瑞瑪智慧谷索爾的大廳向伊崔格接 The Missing Kor'kron（34.28, 39.35），再飛蕨牆村找納澤爾·血矛"}, {"沿東北海岸游往奧卡茲島，在島側軍士處依序交 The Elite of the Elite、Right Place, Wrong Time，拿 No Orc Left Behind 再進島塔地下"}, {"留下 Thrall Needs to Know 至下次奧格瑞瑪"}}, pickAt="04-31", inst={2994}, dq=nil,
