    { id="04-35", start=nil, name="辛特蘭 惡齒村與辛薩羅", map=1425, lv={50, 52}, video="31:48", test=nil, alt=nil, when=nil, tips={{k="取捨", text="值得做｜威士忌斯利姆的酒 和海龜任務同一段海灘完成；梟獸 野蠻的梟獸 與 測試容器 同打。", s={{"值得做｜威士忌斯利姆的酒 和海龜任務同一段海灘完成"}, {"梟獸 野蠻的梟獸 與 測試容器 同打"}}}, {k="取捨", text="可跳過｜職位空缺：惡齒村衛兵隊長 要打 80 隻精英，沒有現成隊伍便略。辛薩羅難以單刷時，先做沿岸與內陸任務。", s={{"可跳過｜職位空缺：惡齒村衛兵隊長 要打 80 隻精英，沒有現成隊伍便略"}, {"辛薩羅難以單刷時，先做沿岸與內陸任務"}}}, {k="取捨", text="先別交｜威士忌斯利姆的酒 到藏寶海灣交；測試容器 到莫沙徹營地交；斯普琳科的秘密佐料、遠古之卵 留塔納利斯 加基森與破碎石柱。", s={{"先別交｜威士忌斯利姆的酒 到藏寶海灣交"}, {"測試容器 到莫沙徹營地交"}, {"斯普琳科的秘密佐料、遠古之卵 留塔納利斯 加基森與破碎石柱"}}}, {k="提醒", text="未到 52 級可在辛特蘭沿岸補海龜、梟獸，或與隊伍清辛薩羅。", s={{"未到 52 級可在辛特蘭沿岸補海龜、梟獸，或與隊伍清辛薩羅"}}}}, dungeon=nil, grind={{mob="海水鉗嘴龜", lv={49, 50}, map=1425, x=83.61, y=57.81, note="惡齒村北側海灘的普通龜，可沿岸直線輪打和剝皮。和採龜肉的玩家共用，無需闖辛薩羅精英區。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
