    { id="04-47", start=nil, name="冬泉谷 永望鎮第一次", map=1452, lv={55, 56}, video="35:33", test=nil, alt=nil, when=nil, tips={{k="交通", text="初到永望鎮開鳥點並綁爐石。下一站飛菲拉斯莫沙徹營地。若未開飛行點，可先飛千針石林亂風崗，沿大路西行到菲拉斯開點。", s={{"初到永望鎮開鳥點並綁爐石"}, {"下一站飛菲拉斯莫沙徹營地"}, {"若未開飛行點，可先飛千針石林亂風崗，沿大路西行到菲拉斯開點"}}}, {k="取捨", text="值得做｜冰火溫泉的多諾瓦任務先交齊，梟獸沿路清；永望鎮雪怪、奇美拉可在同趟做。", s={{"值得做｜冰火溫泉的多諾瓦任務先交齊，梟獸沿路清"}, {"永望鎮雪怪、奇美拉可在同趟做"}}}, {k="取捨", text="可跳過｜尤西烏斯是精英，冬泉熊怪的活動 須往西折返洞口。有隊伍或還缺進度再做。", s={{"可跳過｜尤西烏斯是精英，冬泉熊怪的活動 須往西折返洞口"}, {"有隊伍或還缺進度再做"}}}, {k="取捨", text="之後順路｜永望鎮報告與尼古拉斯公爵的書先放任務欄，東部王國下一輪一起交。", s={{"之後順路｜永望鎮報告與尼古拉斯公爵的書先放任務欄，東部王國下一輪一起交"}}}, {k="提醒", text="還不到56級就打永望鎮東邊的普通雪怪（約64, 40）或東側冬泉村外圍熊怪，避開巡邏精英。", s={{"還不到56級就打永望鎮東邊的普通雪怪（約64, 40）或東側冬泉村外圍熊怪，避開巡邏精英"}}}}, dungeon=nil, grind={{mob="冰薊雪人", lv={55, 56}, map=1452, x=65.24, y=42.38, note="永望鎮東側的普通雪人，靠補給點且可順收毛皮。洞口常有同任務玩家，先沿山腳打。"}, {mob="冬泉巢穴守衛", lv={55, 56}, map=1452, x=66.97, y=34.49, note="冬泉村外圈的普通熊怪，補木喉聲望與相關掉落。村內施法怪容易連拉，避開精英巡邏。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
