    { id="04-48", start=nil, name="菲拉斯 莫沙徹營地短訪", map=1444, lv={55, 56}, video="35:41", test=nil, alt=nil, when=nil, tips={{k="交通", text="主要轉場為永望鎮飛莫沙徹、莫沙徹飛棘齒城。若已安排藏寶海灣交件，可用棘齒城對開的船補交。", s={{"主要轉場為永望鎮飛莫沙徹、莫沙徹飛棘齒城"}, {"若已安排藏寶海灣交件，可用棘齒城對開的船補交"}}}, {k="取捨", text="值得做｜菲拉斯 莫沙徹營地與怒痕堡接、費伍德做的 墮落的力量 是回村就能交的任務。", s={{"值得做｜菲拉斯 莫沙徹營地與怒痕堡接、費伍德做的 墮落的力量 是回村就能交的任務"}}}, {k="取捨", text="可跳過｜海岸支線在西側，定位器沒掉就不找；只有想補經驗或要去雙塔山時才把海岸並入。", s={{"可跳過｜海岸支線在西側，定位器沒掉就不找"}, {"只有想補經驗或要去雙塔山時才把海岸並入"}}}, {k="提醒", text="此站沒有必須單獨練等的門檻。若差56，先到下一站交件，再把經驗差留給後段同等怪區。", s={{"此站沒有必須單獨練等的門檻"}, {"若差56，先到下一站交件，再把經驗差留給後段同等怪區"}}}}, dungeon=nil, grind={{mob="北泉喚風者", lv={49, 50}, map=1444, x=39.89, y=14.49, note="若已在北泉交件，可清營地外圍的普通鷹身人，順收北泉任務掉落。怪等偏低，若還差一大截就去冬泉谷。"}, {mob="冰薊雪人", lv={55, 56}, map=1452, x=65.85, y=41.74, note="若差 56 級，上一站離開永望鎮前優先在這片補。普通雪人集中，外坡比洞口好拉。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
      steps = {
        {t="travel", text="從永望鎮飛莫沙徹營地；這一趟先回營地交菲拉斯 莫沙徹營地與怒痕堡的費伍德支線，已接視靈藥劑再去北邊。", video=true},
        {t="turnin", q=4120, tag="若費伍德森林 血毒崗哨與木喉要塞已完成", npc="塔羅·刺蹄", tgt="塔羅·刺蹄", map=1444, x=76.18, y=43.83},
        {t="travel", text="若身上有 視靈藥劑，沿菲拉斯大道向西至岔路，再朝雙塔山與北邊的烏鴉風廢墟。"},
        {t="do", q=3909, desc="格雷甘交換藥劑是 視靈藥劑 的對話流程；本趟只取藥，別喝，留給冬泉谷多諾瓦交。", tag="若冬泉谷 永望鎮已接", hint="向格雷甘·山酒買誘餌，在北面的米布隆·亂齒腳邊放下，引開守衛後入內取靈根草，再回格雷甘換視靈藥劑。", map=1444, x=45.12, y=25.57, more={{1444, 44.62, 10.52}, {1444, 44.6, 10.18}}},
        {t="travel", opt=true, tag="可跳過", text="打算補海岸支線才去被遺忘的海岸。若手上有菲拉斯定位器，可先去深痕谷洞穴接護送，再順路走到海岸。"},
        {t="accept", q=2766, opt=true, desc="定位器為野怪掉落，已撿到才接。", tag="可跳過", npc="物品 OOX-22/FE定位器", map=1444, x=56.88, y=48.11},
        {t="do", q=2766, opt=true, desc="定位器為野怪掉落，已撿到才接。", tag="可跳過", hint="撿到菲拉斯定位器後點開，在深痕谷附近的洞穴找到導航機器人。", map=1444, x=53.35, y=55.7},
        {t="turnin", q=2766, opt=true, desc="定位器為野怪掉落，已撿到才接。", tag="可跳過", npc="自動導航機器人OOX-22/FE", tgt="自動導航機器人OOX-22/FE", map=1444, x=53.35, y=55.7},
        {t="accept", q=2767, opt=true, desc="沿路有伏擊。護送後交件在藏寶海灣，貧瘠之地 棘齒城若改由藏寶海灣搭船才交。", tag="可跳過", npc="自動導航機器人OOX-22/FE", tgt="自動導航機器人OOX-22/FE", map=1444, x=53.35, y=55.7},
        {t="do", q=2767, opt=true, desc="沿路有伏擊。護送後交件在藏寶海灣，貧瘠之地 棘齒城若改由藏寶海灣搭船才交。", tag="可跳過", hint="護送導航機器人到被遺忘的海岸碼頭。", map=1444, x=53.35, y=55.7, more={{1444, 45.63, 43.39}}},
        {t="accept", q=7003, opt=true, tag="可跳過", npc="索爾賓·范達瑟", tgt="索爾賓·范達瑟", map=1444, x=44.81, y=43.42},
