    { id="04-49", start=nil, name="貧瘠之地 棘齒城短訪", map=1413, lv={55, 56}, video="35:58", test=nil, alt=nil, when=nil, tips={{k="交通", text="棘齒城飛奧格瑪後，換城外幽暗城方向飛艇。抵達提里斯法林地，沿東路到亡靈壁壘。", s={{"棘齒城飛奧格瑪後，換城外幽暗城方向飛艇"}, {"抵達提里斯法林地，沿東路到亡靈壁壘"}}}, {k="取捨", text="值得做｜已完成安戈洛灰燼和車間支線就一起交給莉芙，海岸再接伊斯倫回費伍德的信。", s={{"值得做｜已完成安戈洛灰燼和車間支線就一起交給莉芙，海岸再接伊斯倫回費伍德的信"}}}, {k="取捨", text="可跳過｜若身上沒有棘齒城可交任務，可由菲拉斯直接飛奧格瑪轉飛艇。", s={{"可跳過｜若身上沒有棘齒城可交任務，可由菲拉斯直接飛奧格瑪轉飛艇"}}}, {k="提醒", text="棘齒城的怪等級偏低。未到 56 級可在轉飛艇前飛回永望鎮打東側普通雪人（約 64, 40），或到西瘟疫之地 亡靈壁壘在費爾斯通農場（約 38, 56）打普通亡靈。", s={{"棘齒城的怪等級偏低"}, {"未到 56 級可在轉飛艇前飛回永望鎮打東側普通雪人（約 64, 40），或到西瘟疫之地 亡靈壁壘在費爾斯通農場（約 38, 56）打普通亡靈"}}}}, dungeon=nil, grind={{mob="骷髏巫士", lv={51, 52}, map=1422, x=37.36, y=56.33, note="棘齒城只辦交接。缺 56 級時沿原路搭飛艇，到下一站費爾斯通農場再打。普通骷髏多，從田埂拉，避開血色巡邏。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
