    { id="04-50", start=nil, name="西瘟疫之地 第二次", map=1422, lv={56, 57}, video="36:23", test=nil, alt=nil, when=nil, tips={{k="交通", text="第 1 步由飛艇塔往亡靈壁壘。打完蓋羅恩農場後沿主路向東去東瘟疫。", s={{"第 1 步由飛艇塔往亡靈壁壘"}, {"打完蓋羅恩農場後沿主路向東去東瘟疫"}}}, {k="取捨", text="值得做｜瘟疫之鍋按接續順序做，嚎哭鬼屋順路完成兩段野生動物。", s={{"值得做｜瘟疫之鍋按接續順序做，嚎哭鬼屋順路完成兩段野生動物"}}}, {k="取捨", text="先別交｜返回亡靈壁壘 留西瘟疫之地 亡靈壁壘，瘟疫與妳 在東瘟疫之地 聖光之願禮拜堂完成、回西瘟疫之地 亡靈壁壘交。", s={{"先別交｜返回亡靈壁壘 留西瘟疫之地 亡靈壁壘，瘟疫與妳 在東瘟疫之地 聖光之願禮拜堂完成、回西瘟疫之地 亡靈壁壘交"}}}, {k="提醒", text="同為 56-57 級帶，接著去東瘟疫之地 聖光之願禮拜堂。壁壘旁接了 骸骨碎片 才開始累積骸骨碎片。打算自備通靈學院鑰匙的角色，交完就接 昂貴的模具，並帶兩塊瑟銀錠帶去塔納利斯 加基森，再進安戈洛環形山。", s={{"同為 56-57 級帶，接著去東瘟疫之地 聖光之願禮拜堂"}, {"壁壘旁接了 骸骨碎片 才開始累積骸骨碎片"}, {"打算自備通靈學院鑰匙的角色，交完就接 昂貴的模具，並帶兩塊瑟銀錠帶去塔納利斯 加基森，再進安戈洛環形山"}}}}, dungeon=nil, grind={{mob="恐懼骷髏", lv={52, 54}, map=1422, x=47.54, y=51.36, note="達爾松之淚的普通骷髏，跑瘟疫鍋可順收骸骨碎片。北側會遇到血色巡邏，打外側。"}, {mob="冰冷的食屍鬼", lv={55, 56}, map=1422, x=52.73, y=65.94, note="嚎哭鬼屋附近的普通食屍鬼，等級較合適，和下一口鍋同路。屋門口密集，從田邊開始。"}}, after=nil, entrance=nil, pickup=nil, pickupS=nil, pickAt=nil, inst=nil, dq=nil,
