    [2278] = {xp=4200, mob={{60, 6, 1, 0}}, tgo={{"諾甘農的看門人"}}, d="和石頭守護者交談，從他那裏了解更多古代的知識。壹旦妳了解到了所有的內容之後就激活諾甘農圓盤。", n="白金圓盤", lvl=47, min=40, fol={2280}},
