    [2283] = {xp=2450, mob={{36.3, 6, 2, 1}}, tgo={{"暗爐勘探員", "暗爐惡棍", "暗爐掘地工"}}, d="在奧達曼挖掘場中尋找壹條珍貴的項鏈，然後將其交給奧格瑞瑪的德蘭·杜佛斯。項鏈有可能已經損壞。", n="搜尋項鏈", lvl=41, min=37, rate=0.077, fol={2284}},
    [2284] = {xp=2450, d="在奧達曼裏找尋寶石的線索。", n="搜尋項鏈，再來壹次", lvl=41, min=37, ps={2283}, fol={2318}},
    [2318] = {xp=860, items={7886}, d="在荒蕪之地的卡加斯哨所裏尋找壹個可以幫妳翻譯聖騎士日記的人。", n="翻譯日記", lvl=42, min=37, ps={2284}, fol={2338}},
    [2338] = {xp=345, items={7886}, d="將項鏈借給加卡爾。作為交換，他將幫妳翻譯日記。", n="翻譯日記", lvl=42, min=37, ps={2318}, fol={2339}},
    [2339] = {xp=3750, mob={{0, 0, 1, 0}, {45, 6, 2, 1}, {0, 0, 1, 0}, {47, 6, 2, 1}}, tgo={{}, {"格瑞姆洛克"}, {}, {"阿札達斯"}}, objs={"暗影熔爐地窖", "顯眼的石罐"}, items={7668}, d="從奧達曼找回項鏈上的所有三塊寶石和能量源，然後把它們交給卡加斯的加卡爾。\n紅寶石被藏在暗影矮人層層設防的地區。\n黃寶石藏在石腭怪活動地區的壹個甕中。\n藍寶石在格瑞姆洛克手中，他是石腭怪的領袖。\n能量源可能在奧達曼的某個最強生物的手中。", n="尋找寶貝", lvl=44, min=37, ps={2338}, rate=1, fol={2340}},
    [2340] = {xp=1850, items={7887}, d="把項鏈和寶石送到奧格瑞瑪的德蘭·杜佛斯那裏。", n="交付寶石", lvl=44, min=37, ps={2339}, fol={2341}},
    [2341] = {xp=5600, d="去卡加斯看看加卡爾是否成功了。", n="項鏈任務的終結", lvl=44, min=40, ps={2340}},
    [2342] = {xp=3600, mob={{0, 0, 1, 0}}, objs={"加勒特家族的箱子"}, d="從奧達曼南部大廳的箱子中找到加勒特的家族寶藏，然後把它交給幽暗城的帕特裏克·加瑞特。", n="尋找寶物", lvl=43, min=33},
    [2378] = {xp=115, d="前往奧格瑞瑪，和暗影裂口那的申蘇爾談壹談。", n="尋找碎手氏族", lvl=16, min=16, ex={2380}},
