    [2381] = {xp=1350, mob={{18, 6, 2, 0}}, tgo={{"波利"}}, items={7970, 5060}, d="把南海寶藏帶回給棘齒城的卑鄙的維尼克斯。不要忘了從維尼克斯的機械設備中拿取壹份大餅幹和潛行者工具，妳的任務需要使用這兩件東西。\n如果妳被任何奇怪的鸚鵡攻擊，就對它使用大餅幹！", n="搶劫海盜", lvl=18, min=16, ps={2382}},
    [2382] = {xp=115, d="到棘齒城去，與卑鄙的維尼克斯談壹談。", n="棘齒城的維尼克斯", lvl=16, min=16, ps={2379}, fol={2381}},
    [2383] = {races=2, xp=40, items={12635}, d="閱讀簡易羊皮紙，然後和試煉谷的弗郎恩談壹談。", n="簡易羊皮紙", lvl=1, min=1, ps={788}},
    [2418] = {xp=3500, mob={{40.2, 8, 2, 0}, {40.2, 8, 2, 0}}, tgo={{"暗爐勘探員", "暗爐惡棍", "暗爐掘地工"}, {"暗爐勘探員", "暗爐惡棍", "暗爐掘地工"}}, d="給荒蕪之地的裏格弗茲帶去8塊德提亞姆能量石和8塊安納洛姆能量石。", n="能量石", lvl=36, min=30},
    [2458] = {xp=1150, items={8051}, d="到淤泥沼澤北邊的風險投資公司塔樓去，聯系碎手氏族的臥底費蘇勒。\n看到塔樓之後，用信號槍發射信號，向工頭費蘇勒示意妳已經到達。發出兩個閃光信號，然後使用碎手軍禮和工頭費蘇勒接頭。\n註意，這些步驟必須依次進行，因為費蘇勒會攻擊並幹掉任何他無法識別的人。", n="臥底密探", lvl=20, min=20, ps={2460}, fol={2478}},
    [2460] = {xp=155, mob={{60, 6, 1, 0}}, tgo={{"申蘇爾"}}, d="對著申蘇爾練習碎手軍禮。", n="碎手軍禮", lvl=20, min=20, fol={2458}},
    [2478] = {xp=1950, mob={{25, 6, 1, 0}, {23, 6, 1, 0}, {22, 6, 1, 0}, {23, 6, 2, 1}, {22, 6, 2, 0}, {0, 0, 1, 0}}, tgo={{"變異風險投資公司工人"}, {"風險投資公司看守者"}, {"風險投資公司巡邏員"}, {"大工頭普茲克·加里維克斯"}, {"工頭希里克斯"}, {}}, objs={"加里維克斯的帶鎖箱"}, items={8066}, d="從工頭希裏克斯那裏偷出希裏克斯的塔樓鑰匙，進入塔樓，然後殺掉兩個變異風險投資公司工人、兩個風險投資公司巡邏員、兩個風險投資公司看守。\n殺掉大工頭普茲克·加裏維克斯，取了他的首級，然後打開加裏維克斯的箱子，拿走贊吉爾的改良藥劑。將藥劑和加裏維克斯的頭顱交給奧格瑞瑪的申蘇爾，等候進壹步的指示。", n="基本不可能的任務", lvl=24, min=20, ps={2458}, rate=1, fol={2479}},
    [2479] = {xp=1050, items={8087}, d="到希爾斯布萊德丘陵的塔倫米爾去，把贊吉爾的藥劑樣品交給瑟爾格·希諾特。\n要去塔倫米爾，可以搭乘飛艇到幽暗城，然後沿著大路向南穿過銀松森林，直到希爾斯布萊德丘陵。跟著路標走！", n="希諾特的幫助", lvl=26, min=20, ps={2478}, fol={2480}, chain=true},
    [2480] = {xp=155, d="等待瑟爾格·希諾特完成解藥。", n="希諾特的幫助", lvl=20, min=20, ps={2479}},
    [2521] = {xp=8450, mob={{51.8, 6, 2, 0}}, tgo={{"巨槌巨魔", "巨槌巨魔法師", "巨槌蠻卒"}}, d="在妳探索詛咒之地的旅程中，如果碰巧發現了無暇的德萊尼水晶球，就把它交給收藏家庫米沙。\n妳要知道，這種寶石是整個艾澤拉斯最珍稀的水晶。詛咒之地上的任何壹種生物都有可能帶著壹顆無暇的德萊尼水晶球。\n每找到壹顆，妳都會得到相應的酬勞。", n="為庫米沙效力", lvl=55, min=45},
