    [2583] = {xp=4700, mob={{50.3, 3, 2, 0}, {51.8, 2, 2, 0}, {49.2, 1, 2, 0}}, tgo={{"灰鬃野豬", "地獄野豬", "格朗特"}, {"厚甲毒刺蠍", "搶奪者科拉克"}, {"紅石蜥蜴", "紅石晶鱗蜥蜴", "死眼"}}, d="收集3片詛咒之地的野豬肺、2個厚甲蠍螯和1顆石化蜥蜴的大腦，把它們交給血法師德拉吉亞。", n="野豬的活力", lvl=50, min=45},
