    [5243] = {xp=6600, mob={{0, 0, 1, 0}}, objs={"補給木箱", "斯坦索姆補給木箱"}, d="到北方的斯坦索姆去，尋找散落在城市中的補給箱，並收集5瓶斯坦索姆聖水。當妳找到足夠的聖水之後就回去向萊尼德·巴薩羅梅復命。", n="神聖之屋", lvl=60, min=55},
