    [6481] = {xp=1550, mob={{20, 6, 1, 1}}, tgo={{"高戈羅克"}}, items={16603}, d="使用魔化共鳴水晶打開共鳴桶，然後殺死高戈羅克。將這個消息告訴摩羅加爾，並把魔化共鳴水晶還給他。", n="土靈的覺醒", lvl=20, min=14, ps={6421}},
