    [6565] = {xp=2650, mob={{26, 6, 1, 1}}, tgo={{"洛古斯·傑特"}}, d="殺掉黑暗深淵裏的洛古斯·傑特，然後向灰谷的耶努薩克雷復命。", n="上古之神的仆從", lvl=26, min=17, ps={6564}},
    [6621] = {xp=2650, mob={{26, 6, 2, 0}}, tgo={{"穆戈特酋長"}}, items={16972}, d="把卡拉恩的旗子插到汙林圖騰堆中。不要讓熊怪摧毀這面旗子。擊敗穆戈特酋長，將穆戈特的圖騰交給佐拉姆加的卡拉恩·阿瑪卡。", n="汙林熊怪之王", lvl=26, min=21, ps={216}, rate=1},
    [6626] = {xp=3450, mob={{33.5, 8, 1, 1}, {33.5, 8, 1, 1}, {33.5, 8, 1, 1}}, tgo={{"剃刀沼澤護衛者"}, {"剃刀沼澤織棘者"}, {"亡首教徒"}}, d="殺掉8個剃刀沼澤護衛者、8個剃刀沼澤織棘者和8個亡首教徒，然後向剃刀高地入口處的麥雷姆·月歌復命。", n="邪惡之地", lvl=35, min=28},
    [6627] = {xp=245, d="成功回答布勞格·幽魂的問題，然後和他再次對話。他會壹直在石爪山等妳回答問題。", n="知識試煉", lvl=30, min=25, ps={1154}, fol={1159}},
    [6641] = {xp=2300, d="在穆格拉什尋找火盆的過程中保證他的安全。幫助他撲滅火盆，然後在與納迦作戰時保護他。\n如果妳成功了，就回到佐拉姆加前哨站去，把鞭笞者沃爾沙的死訊通知給戰歌信使。", n="鞭笞者沃爾沙", lvl=23, min=20},
    [6681] = {xp=1950, mob={{1, 6, 1, 0}}, tgo={{"拉文霍德"}}, items={17125}, d="把拉文霍德徽記交給拉文霍德莊園的法拉德，莊園就坐落在希爾斯布萊德的群山之中。\n妳的智慧將在這次旅途中得到考驗。做好準備吧。", n="拉文霍德莊園", lvl=24, min=24, fol={6701}},
    [6701] = {mob={{31.1, 6, 2, 0}}, tgo={{"辛迪加刺客", "辛迪加咒術師", "辛迪加劫匪"}}, n="辛迪加徽章", lvl=60, min=24, ps={6681}},
    [6844] = {xp=3000, items={17346}, d="將異種蠍粘液包裹的物體交給月光林地永夜港的阿姆伯爾，他是塞納裏奧議會的檔案管理員。", n="檔案管理員阿姆伯爾", lvl=57, min=54, ps={1126}, fol={6845}, chain=true},
    [6845] = {xp=7550, d="與月光林地永夜港的拉比恩·薩圖納談壹談。", n="發現過去的秘密", lvl=57, min=54, ps={6844}, fol={1185}},
    [6921] = {xp=2750, mob={{0, 0, 1, 0}}, objs={"深淵之石"}, d="把深淵之核交給灰谷佐拉姆加前哨站裏的耶努薩克雷。", n="廢墟之間", lvl=27, min=21},
    [6922] = {xp=3050, items={16782}, d="把奇怪的水球交給灰谷佐拉姆加前哨站的耶努薩克雷。", n="阿奎尼斯男爵", lvl=30, min=21},
    [6981] = {xp=2650, mob={{15, 6, 1, 0}}, tgo={{"斯布特瓦夫"}}, items={10441}, d="尋找更多有關這塊噩夢碎片的信息。", n="發光的碎片", lvl=26, min=15, fol={3369}},
    [7003] = {xp=4400, mob={{48.3, 15, 2, 0}}, tgo={{"大地行者", "峭壁巨人", "海岸巨人"}}, items={18904}, d="使用索爾賓的超級壓縮器來縮小菲拉斯的任意種類的巨人，將他們縮小到更容易控制的體積。從縮小過的巨人身上收集15份微縮殘渣，把它們交給菲拉斯被遺忘的海岸碼頭的索爾賓·範達瑟。", n="被縮小的巨人", lvl=48, min=45, rate=1},
    [7028] = {xp=5250, mob={{45.7, 25, 2, 0}}, tgo={{"被詛咒的半人馬", "腐爛薩特", "腐爛欺詐者"}}, d="為淒涼之地的維洛收集25個瑟萊德絲水晶雕像。", n="扭曲的邪惡", lvl=47, min=41, rate=0.8},
    [7029] = {xp=5250, mob={{45.5, 6, 1, 0}, {0, 0, 1, 0}}, tgo={{"諾克賽恩幼體"}, {}}, objs={"瑪拉頓橙色水晶池"}, items={17693}, d="在瑪拉頓裏用天藍水瓶在橙色水晶池中裝滿水。\n在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。\n治療8株植物並殺死那些諾克賽恩幼體，然後向葬影村的瓦克·戰痕復命。", n="維利塔恩的汙染", lvl=47, min=41},
    [7044] = {xp=3400, mob={{47, 6, 2, 1}, {47, 6, 2, 0}}, tgo={{"維利塔恩領主"}, {"諾克賽恩", "諾克賽恩產物"}}, d="找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鉆石。\n然後設法和塞雷布拉斯對話。", n="瑪拉頓的傳說", lvl=49, min=41, rate=1, fol={7046}},
    [7046] = {xp=5700, d="幫助贖罪的塞雷布拉斯制作塞雷布拉斯節杖。\n當儀式完成之後再和他談談。", n="塞雷布拉斯節杖", lvl=49, min=41, ps={7044}},
    [7064] = {xp=6100, mob={{51, 6, 1, 1}}, tgo={{"瑟萊德絲公主"}}, d="殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裏復命。", n="大地的汙染", lvl=51, min=45},
    [7066] = {xp=6100, items={17760}, d="到月光林地去找到雷姆洛斯，將生命之種交給他。", n="生命之種", lvl=51, min=45},
    [7067] = {xp=5450, mob={{0, 0, 1, 0}}, items={17781, 17757, 17761, 17762, 17763, 17764, 17765}, d="閱讀賤民的指引，然後從瑪拉頓得到聯合墜飾，將其交給淒涼之地南部的半人馬賤民。", n="賤民的指引", lvl=48, min=39},
    [7068] = {xp=3450, mob={{40, 10, 2, 1}}, tgo={{"裂影巡遊者", "裂影擊碎者", "裂影雷鳴者"}}, d="從瑪拉頓收集10塊暗影殘片，然後把它們交給奧格瑞瑪的尤塞爾奈。", n="暗影殘片", lvl=42, min=39, rate=0.8},
    [7201] = {xp=5450, mob={{54, 10, 2, 1}}, tgo={{"熔岩作戰魔像", "狂怒魔像", "戰鬥傀儡"}}, d="到黑石深淵去取得10份元素精華。妳應該在那些作戰傀儡和傀儡制造者身上找找，另外，薇薇安·拉格雷也提到了壹些有關元素生物的話題……", n="最後的元素", lvl=54, min=48, ps={3906}, rate=0.33},
    [7441] = {xp=7750, mob={{57, 6, 2, 1}}, tgo={{"普希林"}}, d="到厄運之槌去找到小鬼普希林。妳可以使用任何手段從小鬼那裏得到埃斯托爾迪的咒術之書。\n找到咒術之書後，回到拉瑞斯小亭的埃斯托爾迪那裏。", n="普希林和埃斯托爾迪", lvl=58, min=54, rate=1},
    [7461] = {xp=9950, mob={{61, 6, 1, 1}, {60.5, 6, 1, 1}}, tgo={{"伊莫塔爾"}, {"托塞德林王子"}}, d="妳必須幹掉5座水晶塔周圍的守衛，那5座水晶塔維持著關押伊莫塔爾的監獄。壹旦水晶塔的能量被削弱，伊莫塔爾周圍的能量力場就會消散。\n進入伊莫塔爾的監獄，幹掉站在中間的那個惡魔。最後，在圖書館挑戰托塞德林王子。\n當任務完成之後，到庭院中去找辛德拉古靈。", n="伊莫塔爾的瘋狂", lvl=60, min=56, fol={7877}},
    [7463] = {xp=6600, mob={{57, 6, 2, 1}}, tgo={{"海多斯博恩"}}, d="到厄運之槌的扭木廣場去殺掉水元素海多斯博恩。把海多斯博恩精華交給圖書館的博學者萊德羅斯。", n="久違的法師", lvl=60, min=60, rate=1},
    [7481] = {xp=8300, d="到厄運之槌去尋找卡裏爾·溫薩魯斯。向莫沙徹營地的先知科魯拉克報告妳所找到的信息。", n="精靈的傳說", lvl=60, min=54},
