    [7601] = {d="與費伍德森林的伊普斯談壹談。", n="尼比的助手", lvl=50, min=50, fol={7602}},
    [7602] = {xp=5650, mob={{52, 6, 2, 0}, {55, 6, 2, 0}, {54.5, 6, 2, 0}}, tgo={{"雷加斯薩特", "雷加斯盜賊", "雷加斯喚魔者"}, {"加德納爾軍團士兵"}, {"惡魔守衛哨兵"}}, d="費伍德的伊普斯要求妳從三個不同的地區收集三塊無暇的惡魔精華，然後把它們交給他。\n艾薩拉的雷加斯薩特、費伍德森林的加德納爾軍團士兵和詛咒之地的地獄衛士斥候分別擁有壹種無暇的惡魔精華。", n="無暇的惡魔精華", lvl=55, min=50, ps={7601}, rate=0.75, fol={7603}, chain=true},
    [7603] = {xp=7050, mob={{55, 6, 1, 1}, {55, 6, 2, 1}}, tgo={{"克羅蘇斯"}, {"克羅蘇斯"}}, items={18626}, d="在費伍德森林的碎痕谷中搜尋克羅蘇斯的屍體。當妳找到屍體後，在他身上使用魔火，並等待克羅蘇斯復生。當這個地獄火被喚醒之後，幹掉他，從他的身上拿取克羅蘇斯的惡魔之核。\n把克羅蘇斯的惡魔之核交給費伍德森林的尼比。", n="克羅蘇斯的惡魔之核", lvl=55, min=50, ps={7602}, rate=1},
    [7701] = {xp=4700, mob={{50, 6, 2, 1}}, tgo={{"監督者瑪托留斯"}}, d="那個叫做工頭瑪托留斯的黑鐵矮人叛徒就藏在大熔爐的熔渣之池深處。\n殺死工頭瑪托留斯，將他的頭顱交給灼熱峽谷的偵查隊長洛洛爾以換取妳的獎勵。", n="懸賞：工頭瑪托留斯", lvl=50, min=45, rate=1},
    [7721] = {xp=4400, mob={{48, 10, 2, 0}}, tgo={{"海元素", "巨型海元素"}}, d="從菲拉斯被遺忘的海岸那裏的海元素和巨型海元素身上獲取10塊水元素核心，把它們交給碼頭附近的索爾賓·範達瑟。", n="壓縮器的動力", lvl=48, min=45, rate=0.5},
    [7722] = {xp=4700, mob={{0, 0, 1, 0}}, objs={"秘密設計圖:熾熱助熔劑"}, d="在大熔爐的熔渣之池中的某個地方，妳可以找到工頭瑪托留斯偷走的秘密設計圖：熾熱助熔劑。找到這些設計圖，把它們還給灼熱峽谷的大鐵匠博恩奈特。", n="絕密配方！", lvl=50, min=45},
    [7723] = {xp=4550, mob={{48, 20, 1, 0}}, tgo={{"重型作戰魔像"}}, d="漢瑟爾·重拳讓妳殺掉20個重型作戰傀儡。\n重型作戰傀儡就在灼熱峽谷的大熔爐附近。當妳殺死足夠多的傀儡後，就回去找漢瑟爾·重拳。", n="該死的手指頭！", lvl=49, min=45},
    [7724] = {xp=4550, mob={{48, 20, 1, 0}}, tgo={{"巨型熔岩蜘蛛"}}, d="漢瑟爾·重拳要妳殺死灼熱峽谷中的20只巨型熔巖蜘蛛。妳可以在灼熱峽谷的高地和熔巖池裏找到巨型熔巖蜘蛛。\n當妳殺死足夠的巨型熔巖蜘蛛之後，回到漢瑟爾·重拳那裏復命。", n="熔巖蜘蛛的威脅！", lvl=49, min=45},
    [7727] = {xp=4550, mob={{48, 20, 1, 0}}, tgo={{"燻火龍"}}, d="漢瑟爾·重拳讓妳去殺掉20個熏火龍。\n熏火龍侵占了熔渣之池中的那些巖漿池。熔渣之池就在灼熱峽谷的大熔爐中。\n當妳殺死足夠數量的熏火龍後，就回去找漢瑟爾·重拳。", n="熏火龍", lvl=49, min=45},
    [7728] = {xp=4400, mob={{46.5, 6, 2, 0}, {47.5, 6, 2, 0}}, tgo={{"黑鐵鍛造師"}, {"黑鐵監視者"}}, d="找到冶煉鼓風機和偵查員的望遠鏡，把它們還給灼熱峽谷的監工斯克蘭格。\n妳所知道的關於這些物品的惟壹信息是：它們肯定是被黑鐵矮人偷走的。冶煉鼓風機是鐵匠用的鍛造工具，偵查員的望遠鏡是偵查員所需的偵查工具。", n="被盜：鼓風機和望遠鏡", lvl=48, min=45, rate=0.1},
    [7729] = {xp=4400, mob={{47.5, 15, 1, 0}, {45.5, 15, 1, 0}}, tgo={{"黑鐵監工"}, {"黑鐵奴隸販子"}}, d="殺死15個黑鐵工頭和15個黑鐵奴隸販子。完成任務之後就回去找監工斯克蘭格。", n="工作機會：肅清競爭對手", lvl=48, min=45},
    [7730] = {xp=3900, mob={{45.4, 20, 2, 0}}, tgo={{"祖卡什毒刺蠍", "祖卡什異種蠍", "祖卡什工蠍"}}, d="把20塊祖卡什蟲殼交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。", n="祖卡什的入侵", lvl=45, min=39, ps={2903}, rate=1, fol={7732}, chain=true},
    [7731] = {xp=4200, mob={{47, 6, 2, 0}}, tgo={{"毒刺鞭笞者"}}, d="擊敗痛苦深淵中的毒刺鞭笞者，把它的腺體交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。", n="毒刺鞭笞者", lvl=47, min=39, ps={2903}, rate=1, fol={7732}, chain=true},
    [7732] = {xp=4400, items={19020}, d="把莫沙徹營地祖卡什報告交給奧格瑞瑪暗巷區的基爾茲賓·鼓眼。", n="祖卡什報告", lvl=48, min=39, pg={7730, 7731}, fol={4494}, chain=true},
    [7734] = {xp=4400, mob={{47.1, 10, 2, 0}}, tgo={{"狂暴的怒痕雪人", "老年怒痕雪人", "殘忍的怒痕雪人"}}, d="把10塊怒痕雪人的毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。", n="更高的品質", lvl=48, min=40, ps={2822}, rate=0.7},
    [7738] = {xp=2200, items={18972}, d="把完美的雪人毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。", n="完美的雪人毛皮", lvl=48, min=40, ps={2822}},
    [7761] = {xp=6600, d="真是個愚蠢的獸人。看來妳需要找到那枚烙印並獲得達基薩斯徽記才可以使用命令寶珠。\n妳從信中獲知，達基薩斯將軍守衛著烙印。也許妳應該就此進行更深入的調查。", n="黑手的命令", lvl=60, min=55},
    [7815] = {xp=4700, mob={{49.5, 15, 1, 0}}, tgo={{"海水鉗嘴龜"}}, d="辛特蘭惡齒村的釣魚者卡圖姆要妳去殺掉15只海水鉗嘴龜。完成任務之後回到他那裏去復命。", n="鉗嘴龜！", lvl=50, min=44},
    [7816] = {xp=4400, mob={{48, 6, 2, 1}}, tgo={{"加莫里塔"}}, d="辛特蘭惡齒村的釣魚者卡圖姆要妳去殺掉加莫裏塔，並從它的屍體上找到卡圖姆的超級魚餌。\n卡圖姆說加莫裏塔和其它海龜都在海岸附近活動。", n="加莫裏塔！", lvl=48, min=44, rate=1},
    [7828] = {xp=4400, mob={{47.5, 15, 1, 0}, {45.5, 15, 1, 0}}, tgo={{"銀鬃捕獵者"}, {"銀鬃嗥狼"}}, d="辛特蘭惡齒村的獵戶馬克霍爾要求妳去殺掉15頭銀鬃捕獵者和15頭銀鬃嗥狼。完成任務之後就回到他那裏復命。\n馬克霍爾說過那些狼都躲在辛特蘭的野外。", n="銀鬃捕獵者", lvl=48, min=44},
    [7829] = {xp=4400, mob={{46.5, 20, 1, 0}}, tgo={{"野蠻的梟獸"}}, d="辛特蘭惡齒村的獵戶馬克霍爾要求妳去殺掉20頭野蠻的梟獸。完成任務之後就回到他那裏復命。\n馬克霍爾說過那些野蠻的梟獸都躲在辛特蘭的野外。", n="野蠻的梟獸", lvl=48, min=44},
    [7830] = {xp=4400, mob={{47, 6, 2, 0}}, tgo={{"翱翔的鋒喙獅鷲獸"}}, d="辛特蘭惡齒村的獵戶馬克霍爾要求妳殺掉壹頭翺翔的鋒喙獅鷲，並將它的獅鷲長羽拿回去交給他。\n馬克霍爾說過那些翺翔的鋒喙獅鷲就躲在辛特蘭的野外。", n="死者的復仇", lvl=48, min=44, rate=1},
    [7839] = {xp=4400, mob={{0, 0, 1, 0}}, objs={"斯拉提的工具"}, d="辛特蘭惡齒村的鐵匠斯拉提要妳去找到斯拉提的工具。完成任務之後就回到他那裏去。\n妳記得鐵匠斯拉提說過，妳可以在辛特蘭東北部的某個邪枝巨魔神廟中找到它，要不然就是在隱匿石那邊。", n="邪枝竊賊", lvl=48, min=44},
    [7840] = {xp=4550, mob={{49, 6, 2, 0}}, tgo={{"邪枝綁架者"}}, d="辛特蘭惡齒村的拉爾德要求妳去找到拉爾德的午餐。完成任務之後就回到他那裏去。\n拉爾德說他把午餐留在了北面的島上。當心邪枝巨魔。", n="拉爾德的午餐", lvl=49, min=44},
    [7845] = {xp=4900, d="辛特蘭惡齒村的斷齒族長要求妳到辛薩羅去拯救她的愛人，斷齒長者。\n妳聽說他被關在辛薩羅頂部，辛薩羅位於辛特蘭的南部地區，那裏是邪枝巨魔的主城。", n="被綁架的斷齒長者！", lvl=51, min=46, fol={7846}},
    [7846] = {xp=6100, mob={{51, 6, 2, 1}}, tgo={{"看守者希坦亞"}}, d="辛薩羅的斷齒長者要求妳殺掉守護者希坦亞，並用她身上的鐐銬鑰匙打開他的鐐銬。當妳找到鑰匙之後就回到他那裏去。", n="找回鑰匙！", lvl=51, min=46, ps={7845}, rate=1, fol={7847}},
    [7847] = {xp=4900, d="辛薩羅的斷齒長者要求妳將他已經被營救的消息帶給惡齒村的斷齒族長。", n="向斷齒族長復命", lvl=51, min=46, ps={7846}},
    [7848] = {xp=6600, mob={{0, 0, 1, 0}}, objs={"熔核碎片"}, d="進入黑石深淵，在通往熔火之心的傳送門附近找到壹塊熔火碎片，然後回到黑石山脈的洛索斯·天痕那裏。", n="熔火之心的傳送門", lvl=60, min=55},
    [7849] = {xp=5900, mob={{0, 0, 1, 0}, {0, 0, 1, 0}}, objs={"顱骨堆", "白骨堆"}, d="辛特蘭惡齒村的獵戶馬克霍爾要妳去找回他的雙胞胎兄弟的屍體。找到它，然後把獵戶莫克霍爾的頭顱和獵戶莫克霍爾的骨頭交給獵戶馬克霍爾。\n馬克霍爾說過，他兄弟的屍體被軟泥怪和邪枝巨魔的狼群分食。他還提到在辛薩羅有個大坑，裏面全都是軟泥怪，那裏還有個狼穴。這兩個地方都在靠近辛薩羅神廟頂部的區域。", n="分離的痛苦", lvl=50, min=46},
    [7850] = {xp=5900, mob={{0, 0, 1, 0}}, objs={"腐化之血"}, d="辛特蘭惡齒村的斷齒族長要妳在辛薩羅找到10瓶腐化之血。任務完成之後就回到斷齒族長那裏。", n="黑暗之瓶", lvl=50, min=46},
    [7861] = {xp=6100, mob={{51, 20, 1, 1}, {50.5, 1, 1, 1}}, tgo={{"邪惡祭司海克斯"}, {"邪枝精英衛兵"}}, d="妳必須殺掉邪惡祭司海克斯和20名邪枝精英守衛。任務完成之後回到辛特蘭的惡齒村，向斷齒族長報告。\n妳可以在辛特蘭的邪枝巨魔城市辛薩羅的頂部找到他們。", n="通緝：邪惡祭司海克斯和她的爪牙", lvl=51, min=46},
    [7862] = {xp=6100, mob={{47.5, 20, 1, 1}, {48.5, 20, 1, 1}, {49.5, 20, 1, 1}, {49.5, 20, 1, 1}}, tgo={{"邪枝狂戰士"}, {"邪枝暗影獵手"}, {"邪枝飲血者"}, {"邪枝噬魂者"}}, d="妳必須消滅20個邪枝狂戰士、20個邪枝暗影獵手、20個邪枝飲血者和20個邪枝噬魂者。\n完成任務之後向辛特蘭惡齒村的斷齒族長復命。", n="職位空缺：惡齒村衛兵隊長", lvl=51, min=46, star={"衛兵隊長符文", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}},
    [7877] = {xp=660, d="返回圖書館去找到辛德拉的寶藏。拿取妳的獎勵吧！", n="辛德拉的寶藏", lvl=60, min=56, ps={7461}},
    [8151] = {xp=510, d="跟艾薩拉的奧汀克談壹談。", n="獵人的護符", lvl=52, min=50, fol={8153}},
    [8153] = {xp=5100, mob={{52.5, 6, 2, 0}}, tgo={{"苔蹄快步者"}}, d="將壹副完好的苔蹄快步者鹿角交給艾薩拉的奧汀克。奧汀克居住在埃達拉斯廢墟東北部的懸崖頂。", n="苔蹄快步者的鹿角", lvl=52, min=50, ps={8151}, rate=0.08, fol={8231}},
    [8231] = {xp=5100, mob={{52.3, 6, 2, 0}}, tgo={{"幼年碎浪多頭蛇", "碎浪多頭蛇", "大型碎浪多頭蛇"}}, d="將6塊碎浪多頭怪的鱗片交給艾薩拉的奧汀克。奧汀克居住在埃達拉斯廢墟東北部的懸崖頂部。", n="碎浪多頭怪", lvl=52, min=50, ps={8153}, fol={8232}},
    [8232] = {xp=6350, mob={{52, 6, 2, 1}}, tgo={{"摩弗拉斯"}}, d="將摩弗拉斯的牙齒交給艾薩拉的奧汀克。他住在埃達拉斯廢墟東北部懸崖的頂端。", n="神廟中的綠龍", lvl=52, min=50, ps={8231}, star={"魔暴龍眼", {"HUNTER"}}, rate=1},
    [8233] = {xp=510, d="前往拉文霍德莊園，和喬拉齊·拉文霍德公爵談壹談。", n="簡單的要求", lvl=52, min=50, fol={8234}},
    [8234] = {xp=5100, mob={{50.8, 6, 2, 0}}, tgo={{"木喉薩滿", "Blackmaw Shaman"}}, d="從艾薩拉的木喉薩滿祭司那兒取回密封的藍袋子，將它交給艾薩拉的大法師克希雷姆。", n="密封的藍袋子", lvl=52, min=50, fol={8235}, chain=true},
    [8235] = {xp=5100, mob={{52.5, 10, 2, 0}}, tgo={{"森林軟泥怪"}}, d="將10塊密文碎片交給艾薩拉的大法師克希雷姆。", n="密文碎片", lvl=52, min=50, ps={8234}, rate=0.8, fol={8236}},
    [8236] = {xp=6350, mob={{52, 6, 2, 1}}, tgo={{"摩弗拉斯"}}, d="將碧藍鑰匙交給喬拉齊·拉文霍德公爵。", n="碧藍鑰匙", lvl=52, min=50, ps={8235}, star={"暗色蝠斗篷", {"ROGUE"}}, rate=1},
    [8250] = {xp=510, d="找到薩納斯，讓他將妳傳送到大法師克希雷姆那兒。", n="法師的會見", lvl=52, min=50},
    [8251] = {xp=5100, mob={{41.3, 10, 2, 0}}, tgo={{"血精靈勘測員", "血精靈搜尋者", "血精靈防衛者"}}, d="為大法師克希雷姆收集10份閃光塵埃。", n="魔法的塵埃", lvl=52, min=50, rate=0.25, fol={8252}},
    [8252] = {xp=5100, mob={{51, 6, 2, 0}}, tgo={{"惡鞭海妖"}}, d="收集6塊魔化珊瑚，然後把它們交給大法師克希雷姆。", n="納迦的珊瑚", lvl=52, min=50, ps={8251}, rate=0.25, fol={8253}},
    [8253] = {xp=6350, mob={{52, 6, 2, 1}}, tgo={{"摩弗拉斯"}}, d="從摩弗拉斯身上取回奧術碎片，然後返回大法師克希雷姆那兒。", n="毀滅摩弗拉斯", lvl=52, min=50, ps={8252}, star={"火焰寶石", {"MAGE"}}, rate=1},
    [8254] = {xp=510, d="找到艾薩拉的奧汀克。", n="塞納裏奧議會的求助", lvl=52, min=50, fol={8255}},
    [8255] = {xp=5100, mob={{52.5, 4, 2, 0}}, tgo={{"苔蹄快步者"}}, d="收集4份健康的野鹿腺體，把它們交給艾薩拉的奧汀克。奧汀克住在埃達拉斯廢墟東北部懸崖的頂部。", n="苔蹄快步者", lvl=52, min=50, ps={8254}, rate=0.33, fol={8256}},
    [8256] = {xp=5100, mob={{55.1, 6, 2, 0}}, tgo={{"贊吉爾殭屍", "贊吉爾獵人", "骷髏撕掠者"}}, d="為艾薩拉的奧汀克帶回壹份亡靈腐液。奧汀克住在埃達拉斯廢墟東北部懸崖的頂端。", n="亡靈的腐液", lvl=52, min=50, ps={8255}, fol={8257}},
    [8257] = {xp=6350, mob={{52, 6, 2, 1}}, tgo={{"摩弗拉斯"}}, d="前往沈沒的阿塔哈卡神廟，殺死綠龍摩弗拉斯，將他的血液交給費伍德森林中的格雷塔·苔蹄。沈沒的神廟的入口就在悲傷沼澤中。", n="摩弗拉斯之血", lvl=52, min=50, ps={8256}, star={"祝福珠串", {"PRIEST"}}, rate=1},
    [8276] = {xp=2800, d="與希利蘇斯塞納裏奧要塞的喚風者梅恩·長角談壹談。", n="奪回希利蘇斯", lvl=55, min=54, fol={8280}, chain=true},
    [8277] = {xp=5650, mob={{54.5, 8, 2, 0}, {55.5, 8, 2, 0}}, tgo={{"石鞭蠍"}, {"掠沙蜘蛛"}}, d="希利蘇斯塞納裏奧要塞的比提克斯·斯巴格要求妳帶8個石鞭蠍之刺和8個掠沙蜘蛛的牙齒給他。", n="沙漠中的劇毒", lvl=55, min=54, rate=0.18, fol={8278}},
    [8278] = {xp=6000, mob={{57.5, 3, 2, 0}, {56, 3, 2, 0}, {58, 3, 2, 0}}, tgo={{"石鞭撕掠者"}, {"石鞭巨鉗蠍"}, {"石行蜘蛛"}}, d="希利蘇斯塞納裏奧要塞的比提克斯·斯巴格要求妳給他帶去3個石鞭巨鉗蠍之刺、3個石鞭掠奪者之刺和3個石行蜘蛛的牙齒。", n="諾格的最後壹線希望", lvl=57, min=54, ps={8277}},
    [8280] = {xp=5650, mob={{55.5, 15, 1, 0}}, tgo={{"掘泥打擊者"}}, d="希利蘇斯塞納裏奧要塞的喚風者梅恩·長角要求妳去殺死15只掘泥打擊者。", n="保護補給線", lvl=55, min=54, fol={8281}},
    [8281] = {xp=6000, mob={{57.5, 20, 1, 0}}, tgo={{"掘泥摧毀者"}}, d="希利蘇斯塞納裏奧要塞的喚風者梅恩·長角要求妳去殺死20只掘泥摧毀者。", n="確保安全", lvl=57, min=54, ps={8280}},
